        $0 == "## 🔴 High Priority" { priority = "high"; next }
        $0 == "## 🟡 Medium Priority" { priority = "medium"; next }
        $0 == "## 🟢 Nice to Have" { priority = "low"; next }
        /^## / { priority = "" }
        priority != "" && /^- \[ \] / {
            counts[priority]++
            total++
            if (match($0, /\(added: [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]\)$/)) {
                added = substr($0, RSTART + 8, 10)
                if (added < cutoff) stale++
